const INITIAL_CUSTOMERS:Customer[]=[['C-1042','Lakshmi Devi','9876543210','Rampur','Active','Confirmed'],['C-1041','Ravi Kumar','9876543211','Rampur','Active','Pending'],['C-1040','Meena Reddy','9876543212','Kothapalli','Active','Confirmed'],['C-1039','Suresh Patil','9876543213','Bhimnagar','Active','Not verified'],['C-1038','Anita Das','9876543214','Nandipur','Active','Pending'],['C-1037','Mohan Rao','9876543215','Kothapalli','Active','Confirmed'],['C-1036','Fatima Begum','9876543216','Rampur','Active','Confirmed'],['C-1035','Arjun Sen','9876543217','Bhimnagar','Active','Pending']].map(([id,name,phone,village,status,subsidy])=>({id,name,phone,village,status,subsidy}))
