const store={get<T>(key:string,fallback:T):T{try{const x=localStorage.getItem('blueflame:'+key);return x?JSON.parse(x):fallback}catch{return fallback}},set(key:string,val:unknown){localStorage.setItem('blueflame:'+key,JSON.stringify(val))}}
const currency=(n:number)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n)
